INSERT INTO moves
    (id, name, ko_name, type, power, accuracy, pp, category, priority, target, meta_category, ailment, ailment_chance, crit_rate, drain, healing, flinch_chance, stat_chance, min_hits, max_hits, is_contact, is_punch, is_bite, is_sound, is_powder, is_bullet, is_wind, is_slicing, is_dance, is_pulse, is_gravity, is_press, reviewed, description, effect)
VALUES
    (7, 'fire-punch', '불꽃펀치', 'fire', 75, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'burn', 10, 0, 0, 0, 0, 0, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, true, '불꽃을 담은 펀치로 상대를 공격한다. 화상 상태로 만들 때가 있다.', 'Has a chance to burn the target.'),
    (8, 'ice-punch', '냉동펀치', 'ice', 75, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'freeze', 10, 0, 0, 0, 0, 0, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, true, '냉기를 담은 펀치로 상대를 공격한다. 얼음 상태로 만들 때가 있다.', 'Has a chance to freeze the target.'),
    (9, 'thunder-punch', '번개펀치', 'electric', 75, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'paralysis', 10, 0, 0, 0, 0, 0, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, true, '전격을 담은 펀치로 상대를 공격한다. 마비 상태로 만들 때가 있다.', 'Has a chance to paralyze the target.'),
    (12, 'guillotine', '가위자르기', 'normal', NULL, 30, 5, 'physical', 0, 'selected-pokemon', 'ohko', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '큰 집게로 상대를 베어 갈라 공격한다. 맞으면 일격에 기절한다.', 'Causes a one-hit KO.'),
    (14, 'swords-dance', '칼춤', 'normal', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, true, false, false, false, true, '싸움의 춤을 격렬하게 춰서 기세를 높인다. 자신의 공격을 크게 올린다.', 'Raises the user’s Attack by two stages.'),
    (18, 'whirlwind', '날려버리기', 'normal', NULL, NULL, 20, 'status',  -6, 'selected-pokemon', 'force-switch', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, true, false, false, false, false, false, true, '상대를 날려버려서 교대할 포켓몬을 끌어낸다. 야생의 경우에는 배틀이 끝난다.', 'Immediately ends wild battles.  Forces trainers to switch Pokémon.'),
    (19, 'fly', '공중날기', 'flying', 90, 95, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, true, false, true, '1턴째에 하늘을 날아 2턴째에 상대를 공격한다.', 'User flies high into the air, dodging all attacks, and hits next turn.'),
    (20, 'bind', '조이기', 'normal', 15, 85, 20, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'trap', 100, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '긴 몸이나 덩굴 등을 써서 4-5턴 동안 상대를 조여 공격한다.', 'Prevents the target from fleeing and inflicts damage for 2-5 turns.'),
    (25, 'mega-kick', '메가톤킥', 'normal', 120, 75, 5, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '굉장한 힘을 담은 킥으로 상대를 걷어차서 공격한다.', 'Inflicts regular damage with no additional effect.'),
    (32, 'horn-drill', '뿔드릴', 'normal', NULL, 30, 5, 'physical', 0, 'selected-pokemon', 'ohko', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '회전하는 뿔을 상대에게 꿰찔러서 공격한다. 맞으면 일격에 기절한다.', 'Causes a one-hit KO.'),
    (34, 'body-slam', '누르기', 'normal', 85, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'paralysis', 30, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, true, true, '몸 전체로 상대를 덮쳐눌러 공격한다. 마비 상태로 만들 때가 있다.', 'Has a chance to paralyze the target.'),
    (35, 'wrap', '김밥말이', 'normal', 15, 90, 20, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'trap', 100, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '긴 몸이나 덩굴 등을 사용해 4-5턴 동안 상대를 휘감아 공격한다.', 'Prevents the target from fleeing and inflicts damage for 2-5 turns.'),
    (37, 'thrash', '난동부리기', 'normal', 120, 100, 10, 'physical', 0, 'random-opponent', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '2-3턴 동안 마구 난동 부려서 상대를 공격한다. 난동 부린 뒤에는 혼란에 빠진다.', 'Hits every turn for 2-3 turns, then confuses the user.'),
    (38, 'double-edge', '이판사판태클', 'normal', 120, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0,  -33, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '목숨을 걸고 상대에게 돌진하여 공격을 한다. 자신도 상당한 데미지를 입는다.', 'User receives 1/3 the damage inflicted in recoil.'),
    (42, 'pin-missile', '바늘미사일', 'bug', 25, 95, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 5, false, false, false, false, false, false, false, false, false, false, false, false, true, '날카로운 침을 상대에게 발사해서 공격한다. 2-5회 동안 연속으로 쓴다.', 'Hits 2-5 times in one turn.'),
    (44, 'bite', '물기', 'dark', 60, 100, 25, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 30, 0, NULL, NULL, true, false, true, false, false, false, false, false, false, false, false, false, true, '날카롭고 뾰족한 이빨로 물어서 공격한다. 상대를 풀죽게 만들 때가 있다.', 'Has a chance to make the target flinch.'),
    (46, 'roar', '울부짖기', 'normal', NULL, NULL, 20, 'status',  -6, 'selected-pokemon', 'force-switch', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '상대를 도망가게 해서 교대할 포켓몬을 끌어낸다. 야생의 경우에는 배틀이 끝난다.', 'Immediately ends wild battles.  Forces trainers to switch Pokémon.'),
    (47, 'sing', '노래하기', 'normal', NULL, 55, 15, 'status', 0, 'selected-pokemon', 'ailment', 'sleep', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '기분 좋은 예쁜 노랫소리를 들려주고 상대를 잠듦 상태로 만든다.', 'Puts the target to sleep.'),
    (50, 'disable', '사슬묶기', 'normal', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'unique', 'disable', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 움직임을 막아 바로 전에 쓴 기술을 4턴 동안 사용할 수 없게 만든다.', 'Disables the target’s last used move for 1-8 turns.'),
    (53, 'flamethrower', '화염방사', 'fire', 90, 100, 15, 'special', 0, 'selected-pokemon', 'damage-ailment', 'burn', 10, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '세찬 불꽃을 상대에게 발사하여 공격한다. 화상 상태로 만들 때가 있다.', 'Has a chance to burn the target.'),
    (56, 'hydro-pump', '하이드로펌프', 'water', 110, 80, 5, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '대량의 물을 세찬 기세로 상대에게 발사하여 공격한다.', 'Inflicts regular damage with no additional effect.'),
    (57, 'surf', '파도타기', 'water', 90, 100, 15, 'special', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '큰 파도로 자신의 주위에 있는 포켓몬을 공격한다.', 'Inflicts regular damage and can hit Dive users.'),
    (58, 'ice-beam', '냉동빔', 'ice', 90, 100, 10, 'special', 0, 'selected-pokemon', 'damage-ailment', 'freeze', 10, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '냉동빔을 상대에게 발사하여 공격한다. 얼음 상태로 만들 때가 있다.', 'Has a chance to freeze the target.'),
    (59, 'blizzard', '눈보라', 'ice', 110, 70, 5, 'special', 0, 'all-opponents', 'damage-ailment', 'freeze', 10, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, true, false, false, false, false, false, true, '세찬 눈보라를 상대에게 내뿜어 공격한다. 얼음 상태로 만들 때가 있다.', 'Has a chance to freeze the target.'),
    (63, 'hyper-beam', '파괴광선', 'normal', 150, 90, 5, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '강한 광선을 상대에게 발사하여 공격한다. 다음 턴은 움직일 수 없다.', 'User foregoes its next turn to recharge.'),
    (65, 'drill-peck', '회전부리', 'flying', 80, 100, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '회전하면서 뾰족한 부리를 상대에게 꿰찔러 공격한다.', 'Inflicts regular damage with no additional effect.'),
    (67, 'low-kick', '안다리걸기', 'fighting', NULL, 100, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '발을 강하게 걸고 상대를 넘어뜨려 공격한다. 상대가 무거울수록 위력이 올라간다.', 'Inflicts more damage to heavier targets, with a maximum of 120 power.'),
    (68, 'counter', '카운터', 'fighting', NULL, 100, 20, 'physical',  -5, 'specific-move', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '상대로부터 받은 물리공격의 데미지를 2배로 만들어 같은 상대에게 돌려준다.', 'Inflicts twice the damage the user received from the last physical hit it took.'),
    (69, 'seismic-toss', '지구던지기', 'fighting', NULL, 100, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '인력을 사용해 내던진다. 자신의 레벨과 똑같은 데미지를 상대에게 준다.', 'Inflicts damage equal to the user’s level.'),
    (73, 'leech-seed', '씨뿌리기', 'grass', NULL, 90, 10, 'status', 0, 'selected-pokemon', 'ailment', 'leech-seed', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '씨가 뿌려진 상대의 HP를 매 턴 조금씩 흡수하여 자신의 HP를 회복한다.', 'Seeds the target, stealing HP from it every turn.'),
    (74, 'growth', '성장', 'normal', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '몸을 일시에 크게 성장시켜 공격과 특수공격을 올린다.', 'Raises the user’s Attack and Special Attack by one stage.'),
    (76, 'solar-beam', '솔라빔', 'grass', 120, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '1턴째에 빛을 가득 모아 2턴째에 빛의 다발을 발사하여 공격한다.', 'Requires a turn to charge before attacking.'),
    (77, 'poison-powder', '독가루', 'poison', NULL, 75, 35, 'status', 0, 'selected-pokemon', 'ailment', 'poison', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, true, false, false, false, false, false, false, false, true, '독이 있는 가루를 많이 흩뿌려서 상대를 독 상태로 만든다.', 'Poisons the target.'),
    (78, 'stun-spore', '저리가루', 'grass', NULL, 75, 30, 'status', 0, 'selected-pokemon', 'ailment', 'paralysis', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, true, false, false, false, false, false, false, false, true, '저리가루를 많이 흩뿌려서 상대를 마비 상태로 만든다.', 'Paralyzes the target.'),
    (79, 'sleep-powder', '수면가루', 'grass', NULL, 75, 15, 'status', 0, 'selected-pokemon', 'ailment', 'sleep', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, true, false, false, false, false, false, false, false, true, '잠이 오는 가루를 많이 흩뿌려서 상대를 잠듦 상태로 만든다.', 'Puts the target to sleep.'),
