    (87, 'thunder', '번개', 'electric', 110, 70, 10, 'special', 0, 'selected-pokemon', 'damage-ailment', 'paralysis', 30, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '강한 번개를 상대에게 떨어뜨려 공격한다. 마비 상태로 만들 때가 있다.', 'Has a chance to paralyze the target.'),
    (89, 'earthquake', '지진', 'ground', 100, 100, 10, 'physical', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '지진의 충격으로 자신의 주위에 있는 포켓몬을 공격한다.', 'Inflicts regular damage and can hit Dig users.'),
    (90, 'fissure', '땅가르기', 'ground', NULL, 30, 5, 'physical', 0, 'selected-pokemon', 'ohko', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '땅이 갈라진 곳에 상대를 떨어뜨려 공격한다. 맞으면 일격에 기절한다.', 'Causes a one-hit KO.'),
    (91, 'dig', '구멍파기', 'ground', 80, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '1턴째에 파고들어 2턴째에 상대를 공격한다.', 'User digs underground, dodging all attacks, and hits next turn.'),
