    (97, 'agility', '고속이동', 'psychic', NULL, NULL, 30, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '힘을 빼고 몸을 가볍게 해서 고속으로 움직인다. 자신의 스피드를 크게 올린다.', 'Raises the user’s Speed by two stages.'),
    (98, 'quick-attack', '전광석화', 'normal', 40, 100, 30, 'physical', 1, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '눈에 보이지 않는 굉장한 속도로 상대에게 돌진한다. 반드시 선제공격할 수 있다.', 'Inflicts regular damage with no additional effect.'),
    (101, 'night-shade', '나이트헤드', 'ghost', NULL, 100, 15, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '무시무시한 환상을 보게 해서 자신의 레벨과 똑같은 만큼의 데미지를 상대에게 준다.', 'Inflicts damage equal to the user’s level.'),
    (103, 'screech', '싫은소리', 'normal', NULL, 85, 40, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '그만 귀를 막아버리고 싶은 싫은 소리를 내어 상대의 방어를 크게 떨어뜨린다.', 'Lowers the target’s Defense by two stages.'),
    (104, 'double-team', '그림자분신', 'normal', NULL, NULL, 15, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '재빠른 움직임으로 분신을 만들어 상대를 혼란시켜 회피율을 올린다.', 'Raises the user’s evasion by one stage.'),
    (105, 'recover', 'HP회복', 'normal', NULL, NULL, 5, 'status', 0, 'user', 'heal', NULL, 0, 0, 0, 50, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '세포를 재생시켜 자신의 최대 HP의 절반만큼 HP를 회복한다.', 'Heals the user by half its max HP.'),
    (107, 'minimize', '작아지기', 'normal', NULL, NULL, 10, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '몸을 축소하여 작게 보임으로써 자신의 회피율을 크게 올린다.', 'Raises the user’s evasion by two stages.'),
    (109, 'confuse-ray', '이상한빛', 'ghost', NULL, 100, 10, 'status', 0, 'selected-pokemon', 'ailment', 'confusion', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '이상한 빛을 상대에게 비춰 당황하게 한다. 상대를 혼란시킨다.', 'Confuses the target.'),
    (113, 'light-screen', '빛의장막', 'psychic', NULL, NULL, 30, 'status', 0, 'users-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '5턴 동안 이상한 장막을 쳐서 상대로부터 받는 특수공격의 데미지를 약하게 한다.', 'Reduces damage from special attacks by 50% for five turns.'),
    (114, 'haze', '흑안개', 'ice', NULL, NULL, 30, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '흑안개를 뿜어 배틀에 참가 중인 포켓몬 전원의 능력 변화를 원래대로 돌린다.', 'Resets all Pokémon’s stats, accuracy, and evasion.'),
    (115, 'reflect', '리플렉터', 'psychic', NULL, NULL, 20, 'status', 0, 'users-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '5턴 동안 이상한 장막을 쳐서 상대로부터 받는 물리공격의 데미지를 약하게 한다.', 'Reduces damage from physical attacks by half.'),
    (116, 'focus-energy', '기충전', 'normal', NULL, NULL, 30, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '깊게 숨을 들이마셔 기합을 넣는다. 자신의 공격이 급소에 맞기 쉬워진다.', 'Increases the user’s chance to score a critical hit.'),
    (120, 'self-destruct', '자폭', 'normal', 200, 100, 5, 'physical', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '폭발을 일으켜서 자신의 주위에 있는 포켓몬을 공격한다. 쓰고 나서 기절하게 된다.', 'User faints.'),
    (126, 'fire-blast', '불대문자', 'fire', 110, 85, 5, 'special', 0, 'selected-pokemon', 'damage-ailment', 'burn', 10, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '큰 대자의 불꽃으로 상대를 불태운다. 화상 상태로 만들 때가 있다.', 'Has a chance to burn the target.'),
    (127, 'waterfall', '폭포오르기', 'water', 80, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 20, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '굉장한 기세로 상대에게 돌진한다. 상대를 풀죽게 만들 때가 있다.', 'Has a chance to make the target flinch.'),
    (133, 'amnesia', '망각술', 'psychic', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '머리를 비워서 순간적으로 무언가를 잊어버림으로써 자신의 특수방어를 크게 올린다.', 'Raises the user’s Special Defense by two stages.'),
    (136, 'high-jump-kick', '무릎차기', 'fighting', 130, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, true, false, true, '점프해서 무릎차기로 상대를 공격한다. 빗나가면 자신이 데미지를 입는다.', 'If the user misses, it takes half the damage it would have inflicted in recoil.'),
    (137, 'glare', '뱀눈초리', 'normal', NULL, 100, 30, 'status', 0, 'selected-pokemon', 'ailment', 'paralysis', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '배의 무늬로 겁을 주어 상대를 마비 상태로 만든다.', 'Paralyzes the target.'),
    (141, 'leech-life', '흡혈', 'bug', 80, 100, 10, 'physical', 0, 'selected-pokemon', 'damage-heal', NULL, 0, 0, 50, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '피를 빨아서 상대를 공격한다. 준 데미지의 절반을 HP로 회복한다.', 'Drains half the damage inflicted to heal the user.'),
    (143, 'sky-attack', '불새', 'flying', 140, 90, 5, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 1, 0, 0, 30, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '2턴째에 상대를 공격한다. 가끔 풀죽게 만든다. 급소에도 맞기 쉽다.', 'User charges for one turn before attacking.  Has a chance to make the target flinch.'),
    (144, 'transform', '변신', 'normal', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대 포켓몬으로 변신하여 상대와 완전히 똑같은 기술을 사용할 수 있다.', 'User becomes a copy of the target until it leaves battle.'),
    (151, 'acid-armor', '녹기', 'poison', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '세포의 변화로 액체가 되어 자신의 방어를 크게 올린다.', 'Raises the user’s Defense by two stages.'),
    (152, 'crabhammer', '집게해머', 'water', 100, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 1, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '큰 집게를 상대에게 내리쳐서 공격한다. 급소에 맞기 쉽다.', 'Has an increased chance for a critical hit.'),
    (153, 'explosion', '대폭발', 'normal', 250, 100, 5, 'physical', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '큰 폭발로 자신의 주위에 있는 포켓몬을 공격한다. 쓰고 나서는 기절한다.', 'User faints.'),
    (156, 'rest', '잠자기', 'psychic', NULL, NULL, 5, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '2턴 동안 계속 잠잔다. 자신의 HP와 상태 이상을 모두 회복한다.', 'User sleeps for two turns, completely healing itself.'),
    (157, 'rock-slide', '스톤샤워', 'rock', 75, 90, 10, 'physical', 0, 'all-opponents', 'damage', NULL, 0, 0, 0, 0, 30, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '큰 바위를 세차게 부딪쳐서 공격한다. 상대를 풀죽게 만들 때가 있다.', 'Has a chance to make the target flinch.'),
    (161, 'tri-attack', '트라이어택', 'normal', 80, 100, 10, 'special', 0, 'selected-pokemon', 'damage-ailment', 'unknown', 20, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '3개의 광선으로 공격한다. 마비, 화상 또는 얼음 상태 중 어느 하나로 만들 때가 있다.', 'Has a chance to burn, freeze, or paralyze the target.'),
    (162, 'super-fang', '분노의앞니', 'normal', NULL, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '날카로운 앞니로 강하게 물어서 공격한다. 상대의 HP는 절반이 된다.', 'Inflicts damage equal to half the target’s HP.'),
    (164, 'substitute', '대타출동', 'normal', NULL, NULL, 10, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '자신의 HP를 조금 깎아서 분신을 만든다. 분신은 자신의 대타가 된다.', 'Transfers 1/4 of the user’s max HP into a doll, protecting the user from further damage or status changes until it breaks.'),
    (165, 'struggle', '발버둥', 'normal', 50, NULL, 1, 'physical', 0, 'random-opponent', 'damage', NULL, 0, 0, 0,  -25, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '자신의 PP가 떨어지면 발버둥 쳐 상대를 공격한다. 자신도 조금 데미지를 입는다.', 'User takes 1/4 its max HP in recoil.'),
    (168, 'thief', '도둑질', 'dark', 60, 100, 25, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '공격과 동시에 도구를 훔친다. 자신이 도구를 지니고 있을 경우에는 훔칠 수 없다.', 'Takes the target’s item.'),
    (173, 'snore', '코골기', 'normal', 50, 100, 15, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 30, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '자신이 잠들어 있을 때 소음을 내어 공격한다. 상대를 풀죽게 만들 때가 있다.', 'Has a chance to make the target flinch.  Only works if the user is sleeping.'),
    (174, 'curse', '저주', 'ghost', NULL, NULL, 10, 'status', 0, 'specific-move', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '기술을 쓰는 포켓몬이 고스트타입일 때와 그 이외의 타입일 때는 효과가 다르다.', 'Ghosts pay half their max HP to hurt the target every turn.  Others decrease Speed but raise Attack and Defense.'),
    (175, 'flail', '바둥바둥', 'normal', NULL, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '바둥바둥 난동 부려서 공격한다. 자신의 HP가 적을수록 기술의 위력이 올라간다.', 'Inflicts more damage when the user has less HP remaining, with a maximum of 200 power.'),
    (178, 'cotton-spore', '목화포자', 'grass', NULL, 100, 40, 'status', 0, 'all-opponents', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, true, false, false, false, false, false, false, false, true, '솜처럼 폭신폭신한 포자를 착 달라붙게 해서 상대의 스피드를 크게 떨어뜨린다.', 'Lowers the target’s Speed by two stages.'),
    (179, 'reversal', '기사회생', 'fighting', NULL, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '힘을 쥐어짜서 공격한다. 자신의 HP가 적을수록 기술의 위력이 올라간다.', 'Inflicts more damage when the user has less HP remaining, with a maximum of 200 power.'),
    (180, 'spite', '원한', 'ghost', NULL, 100, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대가 마지막으로 사용한 기술에 원한을 품어 그 기술의 PP를 4만큼 줄인다.', 'Lowers the PP of the target’s last used move by 4.'),
    (182, 'protect', '방어', 'normal', NULL, NULL, 10, 'status', 4, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 공격을 전혀 받지 않는다. 연속으로 쓰면 실패하기 쉽다.', 'Prevents any moves from hitting the user this turn.'),
    (183, 'mach-punch', '마하펀치', 'fighting', 40, 100, 30, 'physical', 1, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, true, '눈에 보이지 않는 굉장한 속도로 펀치를 날린다. 반드시 선제공격을 할 수 있다.', 'Inflicts regular damage with no additional effect.'),
    (184, 'scary-face', '겁나는얼굴', 'normal', NULL, 100, 10, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '무서운 얼굴로 노려보고 겁주어 상대의 스피드를 크게 떨어뜨린다.', 'Lowers the target’s Speed by two stages.'),
    (186, 'sweet-kiss', '천사의키스', 'fairy', NULL, 75, 10, 'status', 0, 'selected-pokemon', 'ailment', 'confusion', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '천사처럼 귀엽게 키스하여 상대를 혼란시킨다.', 'Confuses the target.'),
    (187, 'belly-drum', '배북', 'normal', NULL, NULL, 10, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '자신의 HP를 최대 HP의 절반만큼 감소시켜 자신의 공격을 최대로 올린다.', 'User pays half its max HP to max out its Attack.'),
    (188, 'sludge-bomb', '오물폭탄', 'poison', 90, 100, 10, 'special', 0, 'selected-pokemon', 'damage-ailment', 'poison', 30, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, true, '더러운 오물을 상대에게 내던져서 공격한다. 독 상태로 만들 때가 있다.', 'Has a chance to poison the target.'),
    (189, 'mud-slap', '진흙뿌리기', 'ground', 20, 100, 10, 'special', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 얼굴 등에 진흙을 내던져서 공격한다. 명중률을 떨어뜨린다.', 'Has a chance to lower the target’s accuracy by one stage.'),
    (191, 'spikes', '압정뿌리기', 'ground', NULL, NULL, 20, 'status', 0, 'opponents-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 발밑에 압정을 뿌린다. 교체된 상대 포켓몬에게 데미지를 준다.', 'Scatters Spikes, hurting opposing Pokémon that switch in.'),
    (192, 'zap-cannon', '전자포', 'electric', 120, 50, 5, 'special', 0, 'selected-pokemon', 'damage-ailment', 'paralysis', 100, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, true, '대포처럼 전기를 발사해서 공격한다. 상대를 마비 상태로 만든다.', 'Has a chance to paralyze the target.'),
    (194, 'destiny-bond', '길동무', 'ghost', NULL, NULL, 5, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '기술을 쓴 뒤 상대의 공격으로 기절했을 때 공격 상대도 기절하게 한다. 연속으로 쓰면 실패한다.', 'If the user faints this turn, the target automatically will, too.'),
    (195, 'perish-song', '멸망의노래', 'normal', NULL, NULL, 5, 'status', 0, 'all-pokemon', 'ailment', 'perish-song', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '노래를 들은 포켓몬은 3턴이 지나면 기절한다. 교체되면 효과가 없어진다.', 'User and target both faint after three turns.'),
    (196, 'icy-wind', '얼어붙은바람', 'ice', 55, 95, 15, 'special', 0, 'all-opponents', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, true, false, false, false, false, false, true, '차가운 냉기를 상대에게 내뿜어 공격한다. 상대의 스피드를 떨어뜨린다.', 'Has a chance to lower the target’s Speed by one stage.'),
    (197, 'detect', '판별', 'fighting', NULL, NULL, 5, 'status', 4, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 공격을 전혀 받지 않는다. 연속으로 쓰면 실패하기 쉽다.', 'Prevents any moves from hitting the user this turn.'),
    (198, 'bone-rush', '본러시', 'ground', 25, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 5, false, false, false, false, false, false, false, false, false, false, false, false, true, '단단한 뼈로 상대를 세게 때려서 공격한다. 2-5회 동안 연속으로 쓴다.', 'Hits 2-5 times in one turn.'),
    (199, 'lock-on', '록온', 'normal', NULL, NULL, 5, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '조준을 잘 맞춰 다음 공격이 반드시 상대에게 명중하도록 한다.', 'Ensures that the user’s next move will hit the target.'),
    (200, 'outrage', '역린', 'dragon', 120, 100, 10, 'physical', 0, 'random-opponent', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '2-3턴 동안 마구 난동 부려서 공격한다. 난동 부린 뒤에는 혼란에 빠진다.', 'Hits every turn for 2-3 turns, then confuses the user.'),
    (201, 'sandstorm', '모래바람', 'rock', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, true, false, false, false, false, false, true, '5턴 동안 모래바람을 일으켜 바위 땅, 강철타입 이외의 상대에게 데미지를 준다. 바위타입의 특수방어가 올라간다.', 'Changes the weather to a sandstorm for five turns.'),
    (202, 'giga-drain', '기가드레인', 'grass', 75, 100, 10, 'special', 0, 'selected-pokemon', 'damage-heal', NULL, 0, 0, 50, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '양분을 흡수하여 공격한다. 입힌 데미지의 절반에 해당하는 HP를 회복할 수 있다.', 'Drains half the damage inflicted to heal the user.'),
    (203, 'endure', '버티기', 'normal', NULL, NULL, 10, 'status', 4, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '공격을 받아도 HP를 반드시 1만큼은 남긴다. 연속으로 쓰면 실패하기 쉽다.', 'Prevents the user’s HP from lowering below 1 this turn.'),
    (204, 'charm', '애교부리기', 'fairy', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '귀엽게 바라보고 방심을 유도하여 상대의 공격을 크게 떨어뜨린다.', 'Lowers the target’s Attack by two stages.'),
    (207, 'swagger', '뽐내기', 'normal', NULL, 85, 15, 'status', 0, 'selected-pokemon', 'swagger', 'confusion', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대를 화내게 해서 혼란시킨다. 분노로 상대의 공격은 크게 올라가 버린다.', 'Raises the target’s Attack by two stages and confuses the target.'),
    (211, 'steel-wing', '강철날개', 'steel', 70, 90, 25, 'physical', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 10, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '단단한 날개를 상대에게 부딪쳐서 공격한다. 자신의 방어가 올라갈 때가 있다.', 'Has a chance to raise the user’s Defense by one stage.'),
    (212, 'mean-look', '검은눈빛', 'normal', NULL, NULL, 5, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '빨려 들어갈 것 같은 까만 눈빛으로 가만히 응시하여 상대를 배틀에서 도망갈 수 없게 한다.', 'Prevents the target from leaving battle.'),
    (213, 'attract', '헤롱헤롱', 'normal', NULL, 100, 15, 'status', 0, 'selected-pokemon', 'ailment', 'infatuation', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '수컷은 암컷을 암컷은 수컷을 유혹하여 헤롱헤롱하게 만든다. 상대가 기술을 쓰기 어려워진다.', 'Target falls in love if it has the opposite gender, and has a 50% chance to refuse attacking the user.'),
    (214, 'sleep-talk', '잠꼬대', 'normal', NULL, NULL, 10, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '자신이 배운 기술 중 하나를 무작위로 날린다. 자신이 잠들어 있을 때만 쓸 수 있다.', 'Randomly uses one of the user’s other three moves.  Only works if the user is sleeping.'),
    (215, 'heal-bell', '치료방울', 'normal', NULL, NULL, 5, 'status', 0, 'user-and-allies', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '기분 좋은 방울소리를 들려주어 같은 편 전원의 상태 이상을 회복한다.', 'Cures the entire party of major status effects.'),
    (219, 'safeguard', '신비의부적', 'normal', NULL, NULL, 25, 'status', 0, 'users-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '5턴 동안 이상한 힘의 보호를 받아 상태 이상이 되지 않는다.', 'Protects the user’s field from major status ailments and confusion for five turns.'),
    (220, 'pain-split', '아픔나누기', 'normal', NULL, NULL, 20, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '자신의 HP와 상대의 HP를 합친 것을 자신과 상대가 사이좋게 나눈다.', 'Sets the user’s and targets’s HP to the average of their current HP.'),
    (223, 'dynamic-punch', '폭발펀치', 'fighting', 100, 50, 5, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'confusion', 100, 0, 0, 0, 0, 0, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, true, '혼신의 힘으로 펀치를 날려서 공격한다. 상대를 반드시 혼란시킨다.', 'Has a chance to confuse the target.'),
    (224, 'megahorn', '메가혼', 'bug', 120, 85, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '단단하고 훌륭한 뿔로 마음껏 상대를 꿰찔러서 공격한다.', 'Inflicts regular damage with no additional effect.'),
    (226, 'baton-pass', '배턴터치', 'normal', NULL, NULL, 40, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '교대 포켓몬과 바뀐다. 능력 변화는 바뀐 포켓몬이 그대로 이어받는다.', 'Allows the trainer to switch out the user and pass effects along to its replacement.'),
    (227, 'encore', '앙코르', 'normal', NULL, 100, 5, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대에게 앵콜시킨 기술을 3번 연속으로 쓰게 한다.', 'Forces the target to repeat its last used move every turn for 2 to 6 turns.'),
    (229, 'rapid-spin', '고속스핀', 'normal', 50, 100, 40, 'physical', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '회전해서 상대를 공격한다. 조이기, 김밥말이, 씨뿌리기 등을 날려버린다. 자신의 스피드도 오른다.', 'Frees the user from binding moves, removes Leech Seed, and blows away Spikes.'),
    (230, 'sweet-scent', '달콤한향기', 'normal', NULL, 100, 20, 'status', 0, 'all-opponents', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '향기로 상대의 회피율을 크게 떨어뜨린다.', 'Lowers the target’s evasion by one stage.'),
    (231, 'iron-tail', '아이언테일', 'steel', 100, 75, 15, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 30, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '단단한 꼬리로 상대를 힘껏 쳐서 공격한다. 상대의 방어를 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s Defense by one stage.'),
