    (446, 'stealth-rock', '스텔스록', 'rock', NULL, NULL, 20, 'status', 0, 'opponents-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 주위에 무수한 바위를 띄워 교체해서 나온 상대 포켓몬에게 데미지를 준다.', 'Causes damage when opposing Pokémon switch in.'),
    (447, 'grass-knot', '풀묶기', 'grass', NULL, 100, 20, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '풀을 휘감아서 상대를 쓰러뜨린다. 상대가 무거울수록 위력이 올라간다.', 'Inflicts more damage to heavier targets, with a maximum of 120 power.'),
    (450, 'bug-bite', '벌레먹기', 'bug', 60, 100, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '물어서 공격한다. 상대가 나무열매를 지니고 있을 때 먹어서 나무열매의 효과를 받을 수 있다.', 'If target has a berry, inflicts double damage and uses the berry.'),
    (451, 'charge-beam', '차지빔', 'electric', 50, 90, 10, 'special', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 70, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '전격의 다발을 상대에게 발사한다. 전기를 모아서 자신의 특수공격을 올릴 때가 있다.', 'Has a chance to raise the user’s Special Attack by one stage.'),
    (452, 'wood-hammer', '우드해머', 'grass', 120, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0,  -33, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '단단한 몸통을 상대에게 부딪쳐서 공격한다. 자신도 상당한 데미지를 입는다.', 'User receives 1/3 the damage inflicted in recoil.'),
    (453, 'aqua-jet', '아쿠아제트', 'water', 40, 100, 20, 'physical', 1, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '눈에 보이지 않는 굉장한 속도로 상대에게 돌진한다. 반드시 선제공격할 수 있다.', 'Inflicts regular damage with no additional effect.'),
    (457, 'head-smash', '양날박치기', 'rock', 150, 80, 5, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0,  -50, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '목숨을 걸고 혼신의 힘으로 상대에게 박치기를 한다. 자신도 굉장한 데미지를 입는다.', 'User receives 1/2 the damage inflicted in recoil.'),
    (458, 'double-hit', '더블어택', 'normal', 35, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 2, true, false, false, false, false, false, false, false, false, false, false, false, true, '꼬리 등을 써서 상대를 때려 공격한다. 2회 연속으로 데미지를 준다.', 'Hits twice in one turn.'),
    (469, 'wide-guard', '와이드가드', 'rock', NULL, NULL, 10, 'status', 3, 'users-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '같은 편 전원에게 향하는 공격을 1턴 동안 막는다.', 'Prevents any multi-target moves from hitting friendly Pokémon this turn.'),
    (470, 'guard-split', '가드셰어', 'psychic', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '초능력으로 자신과 상대의 방어와 특수방어를 더해서 반으로 나눈다.', 'Averages Defense and Special Defense with the target.'),
    (471, 'power-split', '파워셰어', 'psychic', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '초능력으로 자신과 상대의 공격과 특수공격을 더해서 반으로 나눈다.', 'Averages Attack and Special Attack with the target.'),
    (472, 'wonder-room', '원더룸', 'psychic', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '이상한 공간을 만든다. 5턴 동안 모든 포켓몬의 방어와 특수방어가 바뀐다.', 'All Pokémon’s Defense and Special Defense are swapped for 5 turns.'),
    (473, 'psyshock', '사이코쇼크', 'psychic', 80, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '이상한 염력파를 실체화하여 상대를 공격한다. 물리적인 데미지를 준다.', 'Inflicts damage based on the target’s Defense, not Special Defense.'),
    (474, 'venoshock', '베놈쇼크', 'poison', 65, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '특수한 독액을 끼얹는다. 독 상태의 상대에게는 위력이 2배가 된다.', 'Inflicts double damage if the target is Poisoned.'),
    (476, 'rage-powder', '분노가루', 'bug', NULL, NULL, 20, 'status', 2, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, true, false, false, false, false, false, false, false, true, '안절부절못하게 하는 가루를 자신에게 뿌려서 주의를 끈다. 상대의 공격은 모두 자신에게 향한다.', 'Redirects the target’s single-target effects to the user for this turn.'),
    (478, 'magic-room', '매직룸', 'psychic', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '이상한 공간을 만든다. 5턴 동안 모든 포켓몬의 도구의 효과가 사라진다.', 'Negates held items for five turns.'),
    (479, 'smack-down', '떨어뜨리기', 'rock', 50, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', 'unknown', 100, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '돌이나 구슬을 던져서 날고 있는 상대를 공격한다. 맞은 상대는 땅에 떨어진다.', 'Removes any immunity to Ground damage.'),
    (480, 'storm-throw', '업어후리기', 'fighting', 60, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 6, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '강렬한 일격을 상대에게 날린다. 공격은 반드시 급소에 맞는다.', 'Always scores a critical hit.'),
    (482, 'sludge-wave', '오물웨이브', 'poison', 95, 100, 10, 'special', 0, 'all-other-pokemon', 'damage-ailment', 'poison', 10, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '오물 파도로 자신의 주위에 있는 포켓몬을 공격한다. 독 상태로 만들 때가 있다.', 'Has a chance to poison the target.'),
    (483, 'quiver-dance', '나비춤', 'bug', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, true, false, false, false, true, '신비롭고 아름다운 춤을 경쾌하게 춘다. 자신의 특수공격과 특수방어와 스피드를 올린다.', 'Raises the user’s Special Attack, Special Defense, and Speed by one stage each.'),
    (484, 'heavy-slam', '헤비봄버', 'steel', NULL, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, true, true, '무거운 몸으로 상대에게 부딪쳐 공격한다. 자신이 상대보다 무거울수록 위력이 올라간다.', 'Power is higher when the user weighs more than the target, up to a maximum of 120.'),
    (486, 'electro-ball', '일렉트릭볼', 'electric', NULL, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, true, '전기 덩어리를 상대에게 부딪쳐서 공격한다. 상대보다 스피드가 빠를수록 위력이 올라간다.', 'Power is higher when the user has greater Speed than the target, up to a maximum of 150.'),
    (487, 'soak', '물붓기', 'water', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '많은 물을 끼얹어서 상대를 물타입으로 바꾼다.', 'Changes the target’s type to Water.'),
    (488, 'flame-charge', '니트로차지', 'fire', 50, 100, 20, 'physical', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '불꽃을 둘러 상대를 공격한다. 힘을 모아서 자신의 스피드를 올린다.', 'Inflicts regular damage.  Raises the user’s Speed by one stage.'),
    (489, 'coil', '똬리틀기', 'poison', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '똬리를 틀어서 집중한다. 자신의 공격과 방어와 명중률을 올린다.', 'Raises the user’s Attack, Defense, and accuracy by one stage each.'),
    (490, 'low-sweep', '로킥', 'fighting', 65, 100, 20, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '재빠른 움직임으로 상대의 다리를 노려 공격한다. 상대의 스피드를 떨어뜨린다.', 'Lowers the target’s Speed by one stage.'),
    (491, 'acid-spray', '애시드봄', 'poison', 40, 100, 20, 'special', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, true, '상대를 녹이는 액체를 토해내서 공격한다. 상대의 특수방어를 크게 떨어뜨린다.', 'Lowers the target’s Special Defense by two stages.'),
    (492, 'foul-play', '속임수', 'dark', 95, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 힘을 이용한다. 싸우고 있는 상대의 공격이 높을수록 데미지가 올라간다.', 'Calculates damage with the target’s attacking stat.'),
    (493, 'simple-beam', '심플빔', 'normal', NULL, 100, 15, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '수수께끼의 염력파를 상대에게 보낸다. 염력파를 받은 상대는 특성이 단순으로 바뀐다.', 'Changes the target’s ability to Simple.'),
    (494, 'entrainment', '동료만들기', 'normal', NULL, 100, 15, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '이상한 리듬으로 춤춘다. 움직임을 흉내 내게 해서 자신과 상대의 특성을 똑같게 만든다.', 'Copies the user’s ability onto the target.'),
    (495, 'after-you', '당신먼저', 'normal', NULL, NULL, 15, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 행동을 도와서 자신이 행동한 뒤에 바로 움직일 수 있도록 한다.', 'Makes the target act next this turn.'),
    (496, 'round', '돌림노래', 'normal', 60, 100, 15, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '노래로 상대를 공격한다. 함께 돌림노래를 하면 계속해서 쓸 수 있고 위력도 올라간다.', 'Has double power if it’s used more than once per turn.'),
    (499, 'clear-smog', '클리어스모그', 'poison', 50, NULL, 15, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '특수한 진흙 덩어리를 상대에게 내던져서 공격한다. 능력 변화를 원래대로 돌린다.', 'Removes all of the target’s stat modifiers.'),
    (500, 'stored-power', '어시스트파워', 'psychic', 20, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '축적된 파워로 상대를 공격한다. 자신의 능력이 올라가 있는 만큼 위력이 오른다.', 'Power is higher the more the user’s stats have been raised, to a maximum of 31×.'),
    (501, 'quick-guard', '패스트가드', 'fighting', NULL, NULL, 15, 'status', 3, 'users-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '자신과 같은 편을 상대의 선제공격으로부터 지킨다.', 'Prevents any priority moves from hitting friendly Pokémon this turn.'),
    (502, 'ally-switch', '사이드체인지', 'psychic', NULL, NULL, 15, 'status', 2, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '이상한 힘으로 순간이동하여 자신과 같은 편의 위치를 바꾼다.', 'User switches places with the friendly Pokémon opposite it.'),
    (503, 'scald', '열탕', 'water', 80, 100, 15, 'special', 0, 'selected-pokemon', 'damage-ailment', 'burn', 30, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '뜨겁게 끓어오르는 물을 상대에게 발사해서 공격한다. 화상 상태로 만들 때가 있다.', 'Has a chance to burn the target.'),
    (504, 'shell-smash', '껍질깨기', 'normal', NULL, NULL, 15, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '껍질을 깨서 자신의 방어와 특수방어를 떨어뜨리지만 공격과 특수공격, 스피드를 크게 올린다.', 'Raises user’s Attack, Special Attack, and Speed by two stages.  Lower user’s Defense and Special Defense by one stage.'),
    (505, 'heal-pulse', '치유파동', 'psychic', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'heal', NULL, 0, 0, 0, 50, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, true, false, false, true, '치유파동을 날려서 최대 HP의 절반만큼 상대의 HP를 회복한다.', 'Heals the target for half its max HP.'),
    (506, 'hex', '병상첨병', 'ghost', 65, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '엎친 데 덮친 격으로 공격한다. 상태 이상인 상대에게 큰 데미지를 준다.', 'Has double power if the target has a major status ailment.'),
    (509, 'circle-throw', '배대뒤치기', 'fighting', 60, 90, 10, 'physical',  -6, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '상대를 내던져서 교대할 포켓몬을 끌어낸다. 야생의 경우에는 배틀이 끝난다.', 'Ends wild battles.  Forces trainers to switch Pokémon.'),
    (511, 'quash', '순서미루기', 'dark', NULL, 100, 15, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대를 억눌러서 행동의 순서를 마지막으로 만든다.', 'Makes the target act last this turn.'),
    (512, 'acrobatics', '애크러뱃', 'flying', 55, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '경쾌하게 상대를 공격한다. 자신이 도구를 지니고 있지 않을 때 큰 데미지를 준다.', 'Has double power if the user has no held item.'),
    (513, 'reflect-type', '미러타입', 'normal', NULL, NULL, 15, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 타입을 반사해서 자신도 똑같은 타입이 된다.', 'User becomes the target’s type.'),
    (515, 'final-gambit', '목숨걸기', 'fighting', NULL, 100, 5, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '목숨을 걸고 상대를 공격한다. 자신은 기절하게 되지만 상대에게 HP만큼의 데미지를 준다.', 'Inflicts damage equal to the user’s remaining HP.  User faints.'),
    (517, 'inferno', '연옥', 'fire', 100, 50, 5, 'special', 0, 'selected-pokemon', 'damage-ailment', 'burn', 100, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '격렬한 불꽃으로 상대를 둘러싸 공격한다. 화상 상태로 만든다.', 'Has a chance to burn the target.'),
    (521, 'volt-switch', '볼트체인지', 'electric', 70, 100, 20, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '공격한 뒤 굉장한 스피드로 돌아와서 교대 포켓몬과 교체한다.', 'User must switch out after attacking.'),
    (522, 'struggle-bug', '벌레의저항', 'bug', 50, 100, 20, 'special', 0, 'all-opponents', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '저항해서 상대를 공격한다. 상대의 특수공격을 떨어뜨린다.', 'Has a chance to lower the target’s Special Attack by one stage.'),
    (523, 'bulldoze', '땅고르기', 'ground', 60, 100, 20, 'physical', 0, 'all-other-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '땅을 힘껏 밟아 자신의 주위에 있는 포켓몬을 공격한다. 상대의 스피드를 떨어뜨린다.', 'Has a chance to lower the target’s Speed by one stage.'),
    (524, 'frost-breath', '얼음숨결', 'ice', 60, 90, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 100, 6, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '차가운 숨결을 상대에게 내뿜어 공격한다. 반드시 급소에 맞는다.', 'Always scores a critical hit.'),
    (525, 'dragon-tail', '드래곤테일', 'dragon', 60, 90, 10, 'physical',  -6, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '상대를 튕겨내서 교대할 포켓몬을 끌어낸다. 야생의 경우에는 배틀이 끝난다.', 'Ends wild battles.  Forces trainers to switch Pokémon.'),
    (527, 'electroweb', '일렉트릭네트', 'electric', 55, 95, 15, 'special', 0, 'all-opponents', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '전기 네트로 상대를 붙잡아서 공격한다. 상대의 스피드를 떨어뜨린다.', 'Lowers the target’s Speed by one stage.'),
    (528, 'wild-charge', '와일드볼트', 'electric', 90, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0,  -25, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '전기를 두르고 상대에게 부딪쳐 공격한다. 자신도 조금 데미지를 입는다.', 'User receives 1/4 the damage it inflicts in recoil.'),
    (529, 'drill-run', '드릴라이너', 'ground', 80, 95, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 1, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '드릴처럼 몸을 회전시켜서 상대에게 몸통박치기한다. 급소에 맞기 쉽다.', 'Has an increased chance for a critical hit.'),
    (532, 'horn-leech', '우드혼', 'grass', 75, 100, 10, 'physical', 0, 'selected-pokemon', 'damage-heal', NULL, 0, 0, 50, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '뿔을 꿰찔러서 상대의 양분을 흡수한다. 입힌 데미지의 절반에 해당하는 HP를 회복할 수 있다.', 'Drains half the damage inflicted to heal the user.'),
    (533, 'sacred-sword', '성스러운칼', 'fighting', 90, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, true, '긴 뿔로 베어 공격한다. 상대의 능력 변화에 관계없이 데미지를 준다.', 'Ignores the target’s stat modifiers.'),
    (534, 'razor-shell', '셸블레이드', 'water', 75, 95, 10, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 50, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, true, '날카로운 조개껍질로 베어 공격한다. 상대의 방어를 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s Defense by one stage.'),
    (535, 'heat-crash', '히트스탬프', 'fire', NULL, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, true, true, '불타는 몸으로 상대에게 부딪쳐서 공격한다. 자신이 상대보다 무거울수록 위력이 올라간다.', 'Power is higher when the user weighs more than the target, up to a maximum of 120.'),
    (538, 'cotton-guard', '코튼가드', 'grass', NULL, NULL, 10, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '푹신푹신한 솜털로 자신의 몸을 둘러싸서 지킨다. 방어를 매우 크게 올린다.', 'Raises the user’s Defense by three stages.'),
    (539, 'night-daze', '나이트버스트', 'dark', 85, 95, 10, 'special', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 40, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '암흑의 충격파를 날려서 상대를 공격한다. 명중률을 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s accuracy by one stage.'),
    (541, 'tail-slap', '스위프뺨치기', 'normal', 25, 85, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 5, true, false, false, false, false, false, false, false, false, false, false, false, true, '단단한 꼬리로 상대를 때려서 공격한다. 2-5회 동안 연속으로 쓴다.', 'Hits 2-5 times in one turn.'),
    (542, 'hurricane', '폭풍', 'flying', 110, 70, 10, 'special', 0, 'selected-pokemon', 'damage-ailment', 'confusion', 30, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, true, false, false, false, false, false, true, '강렬한 바람으로 상대를 둘러싸서 공격한다. 상대를 혼란시킬 때가 있다.', 'Has a chance to confuse the target.'),
    (552, 'fiery-dance', '불꽃춤', 'fire', 80, 100, 10, 'special', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 50, NULL, NULL, false, false, false, false, false, false, false, false, true, false, false, false, true, '불꽃을 두른 날개를 쳐서 공격한다. 자신의 특수공격이 오를 때가 있다.', 'Has a chance to raise the user’s Special Attack by one stage.'),
    (555, 'snarl', '바크아웃', 'dark', 55, 95, 15, 'special', 0, 'all-opponents', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '호되게 호통을 쳐서 상대의 특수공격을 떨어뜨린다.', 'Has a chance to lower the target’s Special Attack by one stage.'),
    (556, 'icicle-crash', '고드름떨구기', 'ice', 85, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 30, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '큰 고드름을 격렬하게 부딪쳐서 공격한다. 상대를 풀죽게 만들 때가 있다.', 'Has a chance to make the target flinch.'),
    (560, 'flying-press', '플라잉프레스', 'fighting', 100, 95, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, true, true, true, '공중에서 상대에게 다이브한다. 이 기술은 격투타입임과 동시에 비행타입이기도 하다.', 'Deals both Fighting and Flying-type damage.'),
    (562, 'belch', '트림', 'poison', 120, 90, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대를 향해 트림을 하여 데미지를 준다. 나무열매를 먹지 않으면 쓸 수 없다.', 'Can only be used after the user has eaten a berry.'),
    (564, 'sticky-web', '끈적끈적네트', 'bug', NULL, NULL, 20, 'status', 0, 'opponents-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 주위에 끈적끈적한 네트를 둘러 펼쳐 교체되어 나온 상대의 스피드를 떨어뜨린다.', 'Covers the opposing field, lowering opponents’ Speed by one stage upon switching in.'),
    (565, 'fell-stinger', '마지막일침', 'bug', 50, 100, 25, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '이 기술을 사용하여 상대를 쓰러뜨리면 공격이 매우 크게 오른다.', 'Raises the user’s Attack by two stages if it KOs the target.'),
    (566, 'phantom-force', '고스트다이브', 'ghost', 90, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '1턴째에 어디론가 사라져서 2턴째에 상대를 공격한다. 기술 방어를 무시하고 공격할 수 있다.', 'User vanishes, dodging all attacks, and hits next turn.  Hits through Protect and Detect.'),
    (567, 'trick-or-treat', '핼러윈', 'ghost', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대를 핼러윈으로 초대한다. 상대 타입에 고스트타입이 추가된다.', 'Adds Ghost to the target’s types.'),
    (568, 'noble-roar', '부르짖기', 'normal', NULL, 100, 30, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '우렁차게 부르짖어서 상대를 위협하여 상대의 공격과 특수공격을 떨어뜨린다.', 'Lowers the target’s Attack and Special Attack by one stage.'),
    (570, 'parabolic-charge', '파라볼라차지', 'electric', 65, 100, 20, 'special', 0, 'all-other-pokemon', 'damage-heal', NULL, 0, 0, 50, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '주위에 있는 모든 포켓몬에게 데미지를 준다. 준 데미지의 절반을 자신이 회복한다.', 'Heals the user for half the total damage dealt to all targets.'),
    (571, 'forests-curse', '숲의저주', 'grass', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대에게 숲의 저주를 건다. 저주에 걸린 상대는 타입에 풀타입이 추가된다.', 'Adds Grass to the target’s types.'),
    (572, 'petal-blizzard', '꽃보라', 'grass', 90, 100, 15, 'physical', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, true, false, false, false, false, false, true, '세찬 꽃보라를 일으켜서 주위에 있는 포켓몬을 공격하여 데미지를 준다.', 'Inflicts regular damage.'),
    (573, 'freeze-dry', '프리즈드라이', 'ice', 70, 100, 20, 'special', 0, 'selected-pokemon', 'damage-ailment', 'freeze', 10, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대를 급격히 차갑게 하여 얼음 상태로 만들 때가 있다. 물타입 포켓몬에게도 효과가 굉장해진다.', 'Super-effective against Water.'),
    (575, 'parting-shot', '막말내뱉기', 'dark', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '막말을 내뱉어 상대를 위협하여 공격과 특수공격을 떨어뜨린 후 교대 포켓몬과 교체한다.', 'Lowers all targets’ Attack and Special Attack by one stage.  Makes the user switch out.'),
    (576, 'topsy-turvy', '뒤집어엎기', 'dark', NULL, NULL, 20, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대에게 걸려 있는 모든 능력 변화를 뒤집어서 반대로 만든다.', 'Inverts the target’s stat modifiers.'),
    (577, 'draining-kiss', '드레인키스', 'fairy', 50, 100, 10, 'special', 0, 'selected-pokemon', 'damage-heal', NULL, 0, 0, 75, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '키스로 상대의 HP를 흡수한다. 준 데미지의 반 이상 HP를 회복한다.', 'Drains 75% of the damage inflicted to heal the user.'),
    (580, 'grassy-terrain', '그래스필드', 'grass', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '5턴 동안 그래스필드로 만든다. 땅에 있으면 매 턴 회복한다. 풀타입의 위력이 올라간다.', 'For five turns, heals all Pokémon on the ground for 1/16 max HP each turn and strengthens their Grass moves to 1.5× their power.'),
    (581, 'misty-terrain', '미스트필드', 'fairy', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '5턴 동안 땅에 있으면 상태 이상이 되지 않고 드래곤타입 기술의 데미지도 절반이 된다.', 'For five turns, protects all Pokémon on the ground from major status ailments and confusion, and halves the power of incoming Dragon moves.'),
    (582, 'electrify', '송전', 'electric', NULL, NULL, 20, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대가 기술을 쓰기 전에 송전하면 그 턴에 상대가 사용하는 기술은 전기타입이 된다.', 'Changes the target’s move’s type to Electric if it hasn’t moved yet this turn.'),
    (583, 'play-rough', '치근거리기', 'fairy', 90, 90, 10, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 10, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '상대에게 치근거리며 공격한다. 상대의 공격을 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s Attack by one stage.'),
    (585, 'moonblast', '문포스', 'fairy', 95, 100, 15, 'special', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 30, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '달의 파워를 빌려서 상대를 공격한다. 상대의 특수공격을 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s Special Attack by one stage.'),
    (586, 'boomburst', '폭음파', 'normal', 140, 100, 10, 'special', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '무시무시한 폭음의 파괴력으로 주위에 있는 포켓몬을 공격한다.', 'Inflicts regular damage.'),
    (587, 'fairy-lock', '페어리록', 'fairy', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '록을 걸어 다음 턴의 모든 포켓몬을 도망가지 못하게 한다.', 'Prevents all Pokémon from fleeing or switching out during the next turn.'),
    (588, 'kings-shield', '킹실드', 'steel', NULL, NULL, 10, 'status', 4, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 공격을 막음과 동시에 방어 태세를 갖춘다. 접촉한 상대의 공격을 떨어뜨린다.', 'Blocks damaging attacks and lowers attacking Pokémon’s Attack by two stages on contact.  Switches Aegislash to Shield Forme.'),
    (594, 'water-shuriken', '물수리검', 'water', 15, 100, 20, 'special', 1, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 5, false, false, false, false, false, false, false, false, false, false, false, false, true, '점액으로 만든 수리검을 2-5회 동안 연속으로 던진다. 반드시 선제공격할 수 있다.', 'Hits 2–5 times.'),
    (595, 'mystical-fire', '매지컬플레임', 'fire', 75, 100, 10, 'special', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '입에서 내뱉는 아주 뜨거운 불꽃으로 공격한다. 상대의 특수공격을 떨어뜨린다.', 'Has a chance to lower the target’s Special Attack by one stage.'),
    (596, 'spiky-shield', '니들가드', 'grass', NULL, NULL, 10, 'status', 4, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 공격을 막음과 동시에 접촉한 상대의 체력을 떨어뜨린다.', 'Blocks damaging attacks and damages attacking Pokémon for 1/8 their max HP.'),
    (597, 'aromatic-mist', '아로마미스트', 'fairy', NULL, NULL, 20, 'status', 0, 'ally', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '신비한 아로마 향으로 같은 편의 특수방어를 올린다.', 'Raises a selected ally’s Special Defense by one stage.'),
    (598, 'eerie-impulse', '괴전파', 'electric', NULL, 100, 15, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '몸에서 발생시킨 괴전파를 상대에게 쏘아 특수공격을 크게 떨어뜨린다.', 'Lowers the target’s Special Attack by two stages.'),
    (602, 'magnetic-flux', '자기장조작', 'electric', NULL, NULL, 20, 'status', 0, 'user-and-allies', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '자기장 조작으로 인해 특성 플러스와 마이너스의 방어, 특수방어가 오른다.', 'Raises the Defense and Special Defense of all friendly Pokémon with Plus or Minus by one stage.'),
    (604, 'electric-terrain', '일렉트릭필드', 'electric', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '5턴 동안 일렉트릭필드로 만든다. 땅에 있는 포켓몬은 잠들지 않는다. 전기타입의 위력이 올라간다.', 'For five turns, prevents all Pokémon on the ground from sleeping and strengthens their Electric moves to 1.5× their power.'),
    (605, 'dazzling-gleam', '매지컬샤인', 'fairy', 80, 100, 10, 'special', 0, 'all-opponents', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '강력한 빛을 내어 상대에게 데미지를 준다.', 'Inflicts regular damage with no additional effect.'),
    (608, 'baby-doll-eyes', '초롱초롱눈동자', 'fairy', NULL, 100, 30, 'status', 1, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '초롱초롱한 눈동자로 상대를 바라보며 공격을 떨어뜨린다. 반드시 선제공격할 수 있다.', 'Lowers the target’s Attack by one stage.'),
    (609, 'nuzzle', '볼부비부비', 'electric', 20, 100, 20, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'paralysis', 100, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '전기가 흐르는 볼을 비벼서 공격한다. 상대를 마비 상태로 만든다.', 'Has a chance to paralyze the target.'),
    (611, 'infestation', '엉겨붙기', 'bug', 20, 100, 20, 'special', 0, 'selected-pokemon', 'damage-ailment', 'trap', 100, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '4-5턴 동안 상대에게 엉겨 붙어서 공격한다. 그동안 상대는 도망갈 수 없다.', 'Prevents the target from fleeing and inflicts damage for 2-5 turns.'),
    (617, 'light-of-ruin', '파멸의빛', 'fairy', 140, 90, 5, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0,  -50, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '영원의 꽃의 파워를 빌려서 강력한 광선을 쏜다. 자신도 상당한 데미지를 입는다.', 'User receives 1/2 the damage inflicted in recoil.'),
    (660, 'first-impression', '만나자마자', 'bug', 90, 100, 10, 'physical', 2, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '위력이 높은 기술이지만 배틀에 나가서 바로 쓰지 않으면 성공할 수 없다.', 'Can only be used as the first move after the user enters battle.'),
    (661, 'baneful-bunker', '토치카', 'poison', NULL, NULL, 10, 'status', 4, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 공격을 막음과 동시에 접촉한 상대에게 독을 퍼뜨린다.', 'Grants the user protection for the rest of the turn and poisons any Pokémon that tries to use a contact move on it.'),
    (662, 'spirit-shackle', '그림자꿰매기', 'ghost', 80, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '공격과 동시에 상대의 그림자를 꿰매 도망칠 수 없게 한다.', 'Traps the target.'),
    (663, 'darkest-lariat', 'DD래리어트', 'dark', 85, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '양팔을 돌려 상대에게 부딪친다. 상대의 능력 변화에 상관없이 데미지를 준다.', 'Ignores the target’s stat modifiers.'),
    (664, 'sparkling-aria', '물거품아리아', 'water', 90, 100, 10, 'special', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '노래 부르는 것으로 많은 벌룬을 방출한다. 기술에 맞으면 화상이 낫는다.', 'Cures the target of burns.'),
    (665, 'ice-hammer', '아이스해머', 'ice', 100, 90, 10, 'physical', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, true, '강하고 무거운 주먹을 휘둘러 데미지를 준다. 자신의 스피드가 떨어진다.', 'Lowers user’s Speed by one stage.'),
    (667, 'high-horsepower', '10만마력', 'ground', 95, 95, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '온몸을 써서 상대에게 맹렬히 어택한다.', 'Inflicts regular damage with no additional effect.'),
    (668, 'strength-sap', '힘흡수', 'grass', NULL, 100, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대 공격력과 동일하게 자신의 HP를 회복한다. 그리고 상대의 공격을 떨어뜨린다.', 'Heals the user by the target’s current Attack stat and lowers the target’s Attack by one stage.'),
    (669, 'solar-blade', '솔라블레이드', 'grass', 125, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, true, '1턴째에 빛을 가득 모아 2턴째에 그 힘을 검에 담아 공격한다.', 'Requires a turn to charge before attacking.'),
    (672, 'toxic-thread', '독실', 'poison', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'swagger', 'poison', 100, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '독이 섞인 실을 뿜어낸다. 상대를 독 상태로 만들고 스피드를 떨어뜨린다.', 'Poisons the target and lowers its Speed by one stage.'),
    (675, 'throat-chop', '지옥찌르기', 'dark', 80, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'silence', 100, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '이 기술에 맞은 상대는 지옥의 고통 때문에 2턴 동안 소리 기술을 낼 수 없다.', 'Prevents the target from using sound-based moves for two turns.'),
