    (689, 'instruct', '지휘', 'psychic', NULL, NULL, 15, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대에게 지시하여 상대가 쓴 기술을 다시 한번 쓰게 할 수 있다.', 'Forces the target to repeat its last used move.'),
