    (777, 'decorate', '데코레이션', 'fairy', NULL, NULL, 15, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '데코레이션을 해서 상대의 공격과 특수공격을 크게 올린다.', NULL),
    (779, 'snap-trap', '집게덫', 'grass', 35, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'trap', 100, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '집게덫으로 붙잡은 뒤 4-5턴 동안 상대를 끼워서 공격한다.', 'Prevents the target from fleeing and inflicts damage for 2-5 turns.'),
    (783, 'aura-wheel', '오라휠', 'electric', 110, 100, 10, 'physical', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '볼주머니에 저장해둔 에너지로 공격하고 자신의 스피드를 올린다. 모르페코의 모습에 따라 타입이 바뀐다.', NULL),
    (784, 'breaking-swipe', '와이드브레이커', 'dragon', 60, 100, 15, 'physical', 0, 'all-opponents', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '강인한 꼬리를 세차게 휘둘러서 상대를 공격한다. 상대의 공격을 떨어뜨린다.', 'Lowers the target’s Attack by one stage after inflicting damage.'),
    (787, 'apple-acid', '사과산', 'grass', 80, 100, 10, 'special', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '새콤한 사과에서 만들어 낸 산성 액체로 공격한다. 상대의 특수방어를 떨어뜨린다.', NULL),
    (788, 'grav-apple', 'G의힘', 'grass', 80, 100, 10, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '높은 곳에서 사과를 떨어뜨려서 데미지를 준다. 상대의 방어를 떨어뜨린다.', 'Lowers the target’s Defense by one stage after inflicting damage.'),
    (789, 'spirit-break', '소울크래시', 'fairy', 75, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '맞으면 기가 꺾여버릴 것 같은 기세로 공격한다. 상대의 특수공격을 떨어뜨린다.', 'Has a chance to lower the target’s Special Attack by one stage.'),
    (791, 'life-dew', '생명의물방울', 'water', NULL, NULL, 10, 'status', 0, 'user-and-allies', 'heal', NULL, 0, 0, 0, 25, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '신비한 물을 흩뿌려서 자신과 배틀에 나와 있는 같은 편의 HP를 회복한다.', NULL),
    (796, 'steel-beam', '철제광선', 'steel', 140, 95, 5, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '전신에서 끌어모은 강철을 빔으로 바꿔 세차게 발사한다. 자신도 데미지를 받는다.', 'Inflicts damage, and the user takes damage equal to half of its max HP, rounded up.'),
    (797, 'expanding-force', '와이드포스', 'psychic', 80, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '사이코 파워로 상대를 공격한다. 사이코필드일 때는 위력이 오르며 모든 상대에게 데미지를 준다.', 'Inflicts regular damage with no additional effect.'),
    (798, 'steel-roller', '아이언롤러', 'steel', 130, 100, 5, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '필드를 파괴하면서 공격한다. 필드가 어떤 상태로든 변해 있지 않은 경우 기술은 실패한다.', 'Inflicts regular damage with no additional effect.'),
    (799, 'scale-shot', '스케일샷', 'dragon', 25, 90, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 5, false, false, false, false, false, false, false, false, false, false, false, false, true, '비늘을 쏘아서 공격한다. 2-5회 동안 연속으로 쓴다. 스피드가 올라가지만 방어가 떨어진다.', 'Boosts the user’s Speed and lowers their Defense by one stage after inflicting damage two to five times in a row.'),
    (800, 'meteor-beam', '메테오빔', 'rock', 120, 90, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 100, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '1턴째에 우주의 힘을 모아서 특수공격을 올리고 2턴째에 상대를 공격한다.', 'Inflicts regular damage with no additional effect.'),
    (801, 'shell-side-arm', '셸암즈', 'poison', 90, 100, 10, 'special', 0, 'selected-pokemon', 'damage-ailment', 'poison', 20, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '물리와 특수 중 더 많은 데미지를 줄 수 있는 능력으로 공격한다. 독 상태로 만들 때가 있다.', 'Inflicts regular damage with no additional effect.'),
    (802, 'misty-explosion', '미스트버스트', 'fairy', 100, 100, 5, 'special', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '자신의 주위에 있는 모두를 공격하지만 사용하면 기절한다. 미스트필드일 때 위력이 올라간다.', 'Inflicts regular damage with no additional effect.'),
    (803, 'grassy-glide', '그래스슬라이더', 'grass', 55, 100, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '지면에 미끄러지듯 상대를 공격한다. 그래스필드일 때 반드시 선제공격할 수 있다.', 'Inflicts regular damage with no additional effect.'),
    (804, 'rising-voltage', '라이징볼트', 'electric', 70, 100, 20, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '지면에서 올라오는 전격으로 공격한다. 상대가 일렉트릭필드 위에 있을 때 기술의 위력이 2배가 된다.', 'Inflicts regular damage with no additional effect.'),
    (805, 'terrain-pulse', '대지의파동', 'normal', 50, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, true, false, false, true, '필드의 힘을 빌려서 공격한다. 사용했을 때의 필드 상태에 따라서 기술 타입과 위력이 바뀐다.', 'Inflicts regular damage with no additional effect.'),
    (806, 'skitter-smack', '엄습하는일격', 'bug', 70, 90, 10, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '배후에서 엄습해서 공격한다. 상대의 특수공격을 떨어뜨린다.', 'Inflicts regular damage with no additional effect.'),
    (807, 'burning-jealousy', '질투의불꽃', 'fire', 70, 100, 5, 'special', 0, 'all-opponents', 'damage-ailment', 'burn', 100, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '질투의 에너지로 상대를 공격한다. 그 턴에 능력이 올라간 포켓몬을 화상 상태로 만든다.', 'Inflicts regular damage with no additional effect.'),
    (808, 'lash-out', '분풀이', 'dark', 75, 100, 5, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '상대에 대한 울분이 담긴 공격을 한다. 그 턴에 능력이 떨어져 있으면 기술의 위력이 2배가 된다.', 'Inflicts regular damage with no additional effect.'),
    (809, 'poltergeist', '폴터가이스트', 'ghost', 110, 90, 5, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 지닌 물건을 조종해서 공격한다. 상대가 도구를 지니고 있지 않으면 실패한다.', 'Inflicts regular damage with no additional effect.'),
    (810, 'corrosive-gas', '부식가스', 'poison', NULL, 100, 40, 'status', 0, 'all-other-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '주위에 있는 모든 것을 강력한 산성 가스로 뒤덮어서 지니고 있는 도구를 녹여버린다.', 'Inflicts regular damage with no additional effect.'),
    (811, 'coaching', '코칭', 'fighting', NULL, NULL, 10, 'status', 0, 'user-and-allies', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '적절한 지도를 통해서 같은 편 전원의 공격과 방어를 올린다.', 'Inflicts regular damage with no additional effect.'),
    (812, 'flip-turn', '퀵턴', 'water', 60, 100, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '공격한 뒤 굉장한 스피드로 돌아와서 교대 포켓몬과 교체한다.', 'Inflicts regular damage with no additional effect.'),
    (813, 'triple-axel', '트리플악셀', 'ice', 20, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 3, 3, true, false, false, false, false, false, false, false, false, false, false, false, true, '3회 연속으로 킥을 날려 공격한다. 기술이 맞을 때마다 위력이 올라간다.', 'Inflicts regular damage with no additional effect.'),
    (814, 'dual-wingbeat', '더블윙', 'flying', 40, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 2, true, false, false, false, false, false, false, false, false, false, false, false, true, '날개를 상대에게 부딪쳐서 공격한다. 2회 연속으로 데미지를 준다.', 'Inflicts regular damage with no additional effect.'),
    (815, 'scorching-sands', '열사의대지', 'ground', 70, 100, 10, 'special', 0, 'selected-pokemon', 'damage-ailment', 'burn', 30, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '뜨겁게 달궈진 모래를 상대에게 부딪쳐서 공격한다. 화상 상태로 만들 때가 있다.', 'Has a chance to burn the target.'),
    (826, 'eerie-spell', '섬뜩한주문', 'psychic', 80, 100, 5, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '강력한 사이코 파워로 공격한다. 상대가 마지막으로 사용한 기술의 PP를 3만큼 줄인다.', 'Inflicts regular damage with no additional effect.'),
    (827, 'dire-claw', '페이탈클로', 'poison', 80, 100, 15, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, true, '치명적인 손톱으로 급소를 노려 공격한다. 상대를 독, 마비, 졸음 중 하나의 상태로 만들 때가 있다.', NULL),
    (828, 'psyshield-bash', '배리어러시', 'psychic', 70, 90, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '사념의 에너지를 두른 채로 상대에 부딪힌다. 자신의 방어력이 오를 때가 있다.', NULL),
    (830, 'stone-axe', '암석액스', 'rock', 65, 90, 15, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, true, '암석 도끼로 급소를 노려 공격한다. 흩어진 암석 파편으로 상대에게 여러 번 데미지를 준다.', NULL),
    (833, 'raging-fury', '대격분', 'fire', 120, 100, 10, 'physical', 0, 'random-opponent', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '격렬한 불꽃을 방출하면서 마구 날뛰어 공격한다. 기술을 사용한 다음 열중 상태가 된다.', NULL),
    (834, 'wave-crash', '웨이브태클', 'water', 120, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '물을 두르고 온몸으로 상대에게 부딪친다. 자신도 상당한 데미지를 입는다.', NULL),
    (836, 'mountain-gale', '빙산바람', 'ice', 100, 85, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '빙산처럼 커다란 얼음덩어리를 부딪쳐서 공격한다.', NULL),
    (838, 'headlong-rush', '들이받기', 'ground', 120, 100, 5, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '온 힘을 다한 몸통박치기를 날린다. 자신의 방어력이 떨어진다.', NULL),
    (839, 'barb-barrage', '독침천발', 'poison', 60, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '무수히 많은 독침으로 공격한다. 상대를 독 상태로 만들 때가 있다. 상대가 상태 이상인 경우 위력이 2배가 된다.', NULL),
    (841, 'bitter-malice', '천추지한', 'ghost', 75, 100, 10, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '동굴이 서늘해지는 원념으로 공격해서 상대를 동상 상태로 만들 때가 있다. 상대가 상태 이상인 경우 위력이 2배가 된다.', NULL),
    (842, 'shelter', '농성', 'steel', 0, NULL, 10, 'status', 0, 'user', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '피부를 강철 방패처럼 단단하게 만들어서 자신의 방어력을 올린다. 상대의 기술을 회피하기 쉬워진다.', NULL),
    (843, 'triple-arrows', '3연화살', 'fighting', 90, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '발뒤꿈치로 찍은 뒤 3개의 화살을 동시에 발사한다. 자신의 공격이 급소에 맞기 쉬워진다. 상대의 방어력을 떨어뜨린다.', NULL),
    (844, 'infernal-parade', '백귀야행', 'ghost', 60, 100, 15, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '무수히 많은 불덩이로 공격해서 상대를 화상 상태로 만들 때가 있다. 상대가 상태 이상인 경우 위력이 2배가 된다.', NULL),
    (845, 'ceaseless-edge', '비검천중파', 'dark', 65, 90, 15, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, true, '조개껍질 검으로 급소를 노려 공격한다. 흩어진 조개껍질 파편으로 상대에게 여러 번 데미지를 준다.', NULL),
    (853, 'axe-kick', '발꿈치찍기', 'fighting', 120, 90, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '발꿈치를 들어 올린 뒤 내리찍어 공격한다. 상대를 혼란시킬 때가 있다.빗나가면 자신이 데미지를 입는다.', NULL),
    (854, 'last-respects', '성묘', 'ghost', 50, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '동료의 한을 풀어 주기 위해 공격한다. 쓰러진 같은 편 포켓몬이 많을수록 기술의 위력이 올라간다.', NULL),
    (855, 'lumina-crash', '루미나콜리전', 'psychic', 80, 100, 10, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '정신에도 작용하는 기묘한 빛을 발산해서 공격한다. 상대의 특수방어를 크게 떨어뜨린다.', NULL),
    (857, 'jet-punch', '제트펀치', 'water', 60, 100, 15, 'physical', 1, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, true, '거센 물살을 주먹에 둘러 눈에 보이지 않는 속도로 펀치를 날린다. 반드시 선제공격할 수 있다.', NULL),
    (858, 'spicy-extract', '하바네로엑기스', 'grass', 0, NULL, 15, 'status', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '어마어마하게 매운 엑기스를 발사한다. 상대의 공격이 크게 오르고 방어는 크게 떨어진다.', NULL),
    (860, 'population-bomb', '찍찍베기', 'normal', 20, 90, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, true, '여기저기서 동료들을 모아서 화려한 콤비네이션으로 공격한다. 1~10회 연속으로 공격한다.', NULL),
    (861, 'ice-spinner', '아이스스피너', 'ice', 80, 100, 15, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '발에 얇은 얼음을 두르고 빙글빙글 회전하며 부딪친다. 회전 운동에 의해 필드가 파괴된다.', NULL),
    (863, 'revival-blessing', '회생의기도', 'normal', 0, NULL, 1, 'status', 0, 'fainting-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '자애로운 마음으로 기도를 하여 기절한 교대 포켓몬을 HP가 절반인 상태로 부활시킨다.', NULL),
    (864, 'salt-cure', '소금절이', 'rock', 40, 100, 15, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대를 소금절이 상태로 만들어 매 턴 데미지를 준다. 강철타입이나 물타입에게 더 고통스럽다.', NULL),
    (866, 'mortal-spin', '킬러스핀', 'poison', 30, 100, 15, 'physical', 0, 'all-opponents', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '회전해서 상대를 공격한다. 조이기, 김밥말이, 씨뿌리기 등의 효과를 날려 버린다. 상대를 독 상태로 만든다.', NULL),
    (869, 'kowtow-cleave', '도각참', 'dark', 85, NULL, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, true, '머리를 조아려 상대를 방심하게 만든 뒤에 베어 버린다. 공격은 반드시 명중한다.', NULL),
    (870, 'flower-trick', '트릭플라워', 'grass', 70, NULL, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '숨겨진 장치가 있는 꽃다발을 상대에게 던져서 공격한다. 반드시 명중하며 급소에 맞는다.', NULL),
    (871, 'torch-song', '플레어송', 'fire', 80, 100, 10, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '활활 타오르는 불꽃을 노래하듯 뿜어서 상대를 태워 버린다. 자신의 특수공격을 올린다.', NULL),
    (872, 'aqua-step', '아쿠아스텝', 'water', 80, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, true, false, false, false, true, '물 흐르듯 민첩하고 경쾌한 발재간으로 상대를 농락하여 데미지를 준다.자신의 스피드를 올린다.', NULL),
    (873, 'raging-bull', '레이징불', 'normal', 90, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '분노해 날뛰는 성난소의 맹렬한 태클. 폼에 따라 기술의 타입이 달라지고 빛의장막이나 리플렉터 등도 파괴할 수 있다.', NULL),
    (874, 'make-it-rain', '골드러시', 'steel', 120, 100, 5, 'special', 0, 'all-opponents', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '대량의 코인을 날려서 공격한다. 자신의 특수공격이 떨어진다. 배틀 후에 돈을 받을 수 있다.', NULL),
    (880, 'shed-tail', '꼬리자르기', 'normal', 0, NULL, 10, 'status', 0, 'user', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '사용자 HP의 1/2를 깎아서 대타가 되는 분신을 만든 다음, 교대 포켓몬과 교체한다.', NULL),
    (881, 'chilly-reception', '썰렁개그', 'ice', 0, NULL, 10, 'status', 0, 'entire-field', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '자리를 얼어붙게 만드는 개그를 하고 교대 포켓몬과 교체한다. 5턴 동안 눈을 내리게 한다.', NULL),
    (882, 'tidy-up', '정리정돈', 'normal', 0, NULL, 10, 'status', 0, 'user', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '압정뿌리기, 스텔스록, 끈적끈적네트, 독압정, 대타출동을 모두 정리한다. 자신의 공격과 스피드가 올라간다.', NULL),
    (883, 'snowscape', '설경', 'ice', 0, NULL, 10, 'status', 0, 'entire-field', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '5턴 동안 눈을 내리게 한다. 얼음타입의 방어가 올라간다.', NULL),
    (884, 'pounce', '달려들기', 'bug', 50, 100, 20, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '상대에게 달려들어 공격한다. 상대의 스피드를 떨어뜨린다.', NULL),
    (885, 'trailblaze', '개척하기', 'grass', 50, 100, 20, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '풀숲에서 튀어나오듯이 공격한다. 경쾌한 발재간으로 자신의 스피드를 올린다.', NULL),
    (886, 'chilling-water', '찬물끼얹기', 'water', 50, 100, 20, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '상대의 기운이 빠질 정도로 차가운 물을 끼얹어서 공격한다. 상대의 공격을 떨어뜨린다.', NULL),
    (888, 'twin-beam', '트윈빔', 'psychic', 40, 100, 10, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '두 눈에서 불가사의한 광선을 발사해서 공격한다. 2회 연속으로 데미지를 준다.', NULL),
    (889, 'rage-fist', '분노의주먹', 'ghost', 50, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, true, '분노를 에너지로 바꿔서 공격한다. 받은 공격의 횟수가 많을수록 기술의 위력이 올라간다.', NULL),
    (890, 'armor-cannon', '아머캐논', 'fire', 120, 100, 5, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '자신의 갑옷을 활활 타오르는 탄환으로 발사해서 공격한다. 자신의 방어와 특수방어가 떨어진다.', NULL),
    (891, 'bitter-blade', '원념의칼', 'fire', 90, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, true, '현세의 미련을 칼끝에 담아 베어 버린다. 입힌 데미지의 절반에 해당하는 HP를 회복할 수 있다.', NULL),
    (892, 'double-shock', '전광쌍격', 'electric', 120, 100, 5, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '전신의 전기를 모두 방출해서 큰 데미지를 준다. 자신의 전기타입이 없어진다.', NULL),
    (893, 'gigaton-hammer', '거대해머', 'steel', 160, 100, 5, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '거대한 해머를 온몸으로 휘둘러서 공격한다. 이 기술은 2회 연속으로 쓸 수 없다.', NULL),
    (894, 'comeuppance', '앙갚음', 'dark', 1, 100, 10, 'physical', 0, 'specific-move', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '기술을 쓰기 전에 마지막으로 받은 기술의 데미지를 늘려서 기술을 쓴 상대에게 돌려준다.', NULL),
    (895, 'aqua-cutter', '아쿠아커터', 'water', 70, 100, 20, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, true, false, false, false, false, true, '압력을 가한 물을 칼날처럼 분사해서 상대를 베어 가른다. 급소에 맞기 쉽다.', NULL),
    (902, 'matcha-gotcha', '휘적휘적포', 'grass', 80, 90, 15, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '휘저은 차를 대포처럼 발사해 준 데미지의 절반을 HP로 회복한다. 화상 상태로 만들 때도 있다.', NULL),
    (903, 'syrup-bomb', '시럽봄', 'grass', 60, 85, 10, 'special', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, true, '끈적끈적한 물엿을 폭발시킨다. 상대를 물엿범벅 상태로 만들어서 3턴 동안 계속 스피드를 떨어뜨린다', NULL),
    (905, 'electro-shot', '일렉트로빔', 'electric', 130, 100, 10, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '1턴째에 전기를 모아서 특수공격을 올리고 2턴째에 고압의 전기를 발사한다. 비가 오는 날씨일 때는 바로 발사할 수 있다.', NULL),
    (907, 'fickle-beam', '변덕레이저', 'dragon', 80, 100, 5, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, true, '광선을 발사해서 공격한다. 가끔 다른 머리도 협력해서 레이저를 발사하여 위력이 2배가 된다.', NULL),
    (912, 'hard-press', '하드프레스', 'steel', 0, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '팔이나 집게로 상대를 압박한다. 상대의 HP가 남아 있을수록 위력이 올라간다.', NULL),
    (913, 'dragon-cheer', '드래곤옐', 'dragon', 0, 0, 15, 'status', 0, 'all-allies', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '용의 북돋움으로 사기를 높여서 같은 편의 기술이 급소에 맞기 쉬워진다. 드래곤타입이면 더욱더 사기가 북돋는다.', NULL),
    (914, 'alluring-voice', '매혹의보이스', 'fairy', 80, 100, 10, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '천사와도 같은 노랫소리로 상대를 공격한다.그 턴에 능력이 올라간 포켓몬을 혼란 상태로 만든다.', NULL),
    (915, 'temper-flare', '열불내기', 'fire', 75, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '자포자기하는 자세로 공격한다. 앞 턴에서 기술이 빗나갔다면 위력이 배가 된다.', NULL),
    (916, 'supercell-slam', '썬더다이브', 'electric', 100, 95, 15, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '몸에 전기를 두르고 상대를 덮친다. 빗나가면 자신이 데미지를 입는다.', NULL),
    (917, 'psychic-noise', '사이코노이즈', 'psychic', 75, 100, 10, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, true, '불쾌한 음파를 상대에게 날려서 공격한다. 2턴 동안 상대는 기술이나 특성 또는 지니고 있는 도구로 HP를 회복할 수 없게 된다.', NULL),
    (918, 'upper-hand', '기선제압', 'fighting', 65, 100, 15, 'physical', 3, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, true, '움직임에 반응하여 손바닥으로 밀쳐서 상대를 풀죽게 한다. 상대가 쓴 기술이 선제공격 기술이 아니면 실패한다.', NULL);
